create or replace function public.kleenest_map_check_in(p_location_id uuid,p_lat double precision default null,p_lng double precision default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); cid uuid; awarded integer:=10; result jsonb; begin if uid is null then raise exception 'AUTH_REQUIRED'; end if; insert into public.check_ins(user_id,location_id,latitude,longitude,verification_method,points_awarded,metadata) values(uid,p_location_id,p_lat,p_lng,'gps',awarded,jsonb_build_object('source','maps')) returning id into cid; insert into public.point_transactions(user_id,points,reason,reference_id) values(uid,awarded,'map_check_in',cid); update public.profiles set points=points+awarded,total_check_ins=total_check_ins+1,updated_at=now() where id=uid; insert into public.analytics_events(event_type,location_id,user_id,metadata) values('check_in',p_location_id,uid,jsonb_build_object('source','maps')); return jsonb_build_object('success',true,'check_in_id',cid,'points_awarded',awarded); end $$; grant execute on function public.kleenest_map_check_in(uuid,double precision,double precision) to authenticated;
create or replace function public.kleenest_toggle_favorite(p_location_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); nowfav boolean; begin if uid is null then raise exception 'AUTH_REQUIRED'; end if; if exists(select 1 from public.favorites where user_id=uid and location_id=p_location_id) then delete from public.favorites where user_id=uid and location_id=p_location_id; nowfav:=false; insert into public.analytics_events(event_type,location_id,user_id,metadata) values('favorite_removed',p_location_id,uid,jsonb_build_object('source','maps')); else insert into public.favorites(user_id,location_id) values(uid,p_location_id); nowfav:=true; insert into public.analytics_events(event_type,location_id,user_id,metadata) values('favorite_added',p_location_id,uid,jsonb_build_object('source','maps')); end if; return jsonb_build_object('success',true,'favorite',nowfav); end $$; grant execute on function public.kleenest_toggle_favorite(uuid) to authenticated;
create or replace function public.kleenest_map_view(p_location_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin insert into public.analytics_events(event_type,location_id,user_id,metadata) values('location_view',p_location_id,auth.uid(),jsonb_build_object('source','maps')); end $$; grant execute on function public.kleenest_map_view(uuid) to authenticated;
